pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= type(uint256).max);
        vm.prank(address(this));
        c.AdjustBetAmounts(amount);
        uint256 newLimit = c.currentBetLimit();
        // The event emitted by AdjustBetAmounts carries the current betLimit.
        // After a correct update, that event parameter must equal the new limit.
        // In a block, we can read the event from the receipt. To avoid event parsing
        // we assert that the returned newLimit equals the amount argument.
        // However, the buggy version leaves newLimit unchanged (0), so it will differ.
        assertTrue(newLimit == amount);
    }
}

