pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 oldAmount, uint256 newAmount) public {
        // restrict to admissible domain: owner must be able to call, no overflow assumptions needed
        vm.assume(oldAmount != newAmount);
        vm.assume(newAmount <= type(uint256).max - 1); // avoid overflow in mutant's +1
        vm.assume(oldAmount <= type(uint256).max - 1);

        // Set initial betLimit
        vm.prank(address(this));
        c.AdjustBetAmounts(oldAmount);
        uint256 initialLimit = c.currentBetLimit();

        // Change to new amount
        vm.prank(address(this));
        c.AdjustBetAmounts(newAmount);
        uint256 finalLimit = c.currentBetLimit();

        // General rule: change in betLimit equals change in amount (newAmount - oldAmount)
        uint256 limitDelta = finalLimit - initialLimit;
        uint256 amountDelta = newAmount - oldAmount;
        assertTrue(limitDelta == amountDelta);
    }
}

