pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount, uint256 prevAmount) public {
        vm.assume(prevAmount <= type(uint256).max - 1);
        vm.prank(address(this));
        c.AdjustBetAmounts(prevAmount);
        uint256 beforeLimit = c.currentBetLimit();
        vm.prank(address(this));
        c.AdjustBetAmounts(amount);
        uint256 afterLimit = c.currentBetLimit();
        uint256 expectedDelta;
        if (amount >= prevAmount) {
            expectedDelta = amount - prevAmount;
        } else {
            expectedDelta = type(uint256).max - prevAmount + amount + 1;
        }
        if (amount > prevAmount) {
            assertTrue(afterLimit - beforeLimit == expectedDelta);
        } else if (amount < prevAmount) {
            assertTrue(beforeLimit - afterLimit == prevAmount - amount);
        } else {
            assertTrue(afterLimit == beforeLimit);
        }
    }
}

